const customerView=document.querySelector('#customers');
customerView.innerHTML='<div class="view-head"><div><h2>Pelanggan</h2><p>Data akun dan riwayat pembelian pelanggan.</p></div></div><div class="tools"><input class="search" id="customerSearch" type="search" placeholder="Cari nama, email, atau telepon…"></div><section class="panel table-wrap"><table class="table"><thead><tr><th>Pelanggan</th><th>Kontak</th><th>Pesanan</th><th>Total berhasil</th><th>Terakhir</th><th>Aksi</th></tr></thead><tbody id="customerRows"></tbody></table></section>';
let customerData=[];
const formatDate=value=>value?new Date(value.endsWith?.('Z')?value:`${value}Z`).toLocaleDateString('id-ID'):'—';
function renderCustomers(){const query=document.querySelector('#customerSearch').value.toLowerCase(),rows=customerData.filter(item=>`${item.name} ${item.email} ${item.phone}`.toLowerCase().includes(query));document.querySelector('#customerRows').innerHTML=rows.length?rows.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong><br><small>${escapeHtml(item.email)}</small></td><td>${escapeHtml(item.phone)}</td><td>${item.orderCount}</td><td>${rupiah(item.totalSpent)}</td><td>${formatDate(item.lastOrderAt)}</td><td><button class="icon-btn customer-detail" data-id="${item.id}">Detail</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Pelanggan tidak ditemukan.</td></tr>';document.querySelectorAll('.customer-detail').forEach(button=>button.addEventListener('click',()=>openCustomer(button.dataset.id)))}
async function loadCustomers(){document.querySelector('#customerRows').innerHTML='<tr><td colspan="6" class="empty">Memuat pelanggan…</td></tr>';try{const data=await api('/api/customers');customerData=data.customers;renderCustomers()}catch(error){toast(error.message)}}
document.querySelector('#customerSearch').addEventListener('input',renderCustomers);document.querySelector('.menu button[data-view="customers"]').addEventListener('click',loadCustomers);
const customerModal=document.createElement('dialog');customerModal.className='modal order-modal';customerModal.innerHTML='<div class="modal-inner"><div class="modal-head"><h2 id="customerModalTitle">Detail pelanggan</h2><button class="close" type="button" aria-label="Tutup">×</button></div><div class="order-detail" id="customerModalContent"></div></div>';document.body.append(customerModal);customerModal.querySelector('.close').addEventListener('click',()=>customerModal.close());
async function openCustomer(id){customerModal.showModal();const content=document.querySelector('#customerModalContent');content.innerHTML='<div class="empty">Memuat detail…</div>';try{const data=await api(`/api/customers/${id}`),customer=data.customer;document.querySelector('#customerModalTitle').textContent=customer.name;content.innerHTML=`<div class="order-summary-grid"><div class="order-box"><small>Email</small><strong>${escapeHtml(customer.email)}</strong></div><div class="order-box"><small>Telepon</small><strong>${escapeHtml(customer.phone)}</strong></div><div class="order-box"><small>Terdaftar</small><strong>${formatDate(customer.createdAt)}</strong></div><div class="order-box"><small>Login terakhir</small><strong>${formatDate(customer.lastLoginAt)}</strong></div></div><div><strong>Alamat tersimpan</strong><div class="customer-addresses">${data.addresses.length?data.addresses.map(address=>`<div class="order-box"><strong>${escapeHtml(address.label)}</strong><div>${escapeHtml(address.address)}</div><small>${escapeHtml(address.city)} · ${escapeHtml(address.postalCode)}</small></div>`).join(''):'<div class="empty">Belum ada alamat.</div>'}</div></div><div><strong>Riwayat pesanan</strong><div class="order-lines">${data.orders.length?data.orders.map(order=>`<div class="order-line"><span><strong>${escapeHtml(order.id)}</strong><small>${formatDate(order.createdAt)} · ${escapeHtml(order.status)}</small></span><strong>${rupiah(order.total)}</strong></div>`).join(''):'<div class="empty">Belum ada pesanan.</div>'}</div></div>`}catch(error){content.innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}

const reportsMenu=document.createElement('button');reportsMenu.type='button';reportsMenu.dataset.view='reports';reportsMenu.setAttribute('aria-label','Laporan');reportsMenu.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke-width="2"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg><span>Laporan</span>';const settingsMenuButton=document.querySelector('.menu button[data-view="settings"]');document.querySelector('.menu').insertBefore(reportsMenu,settingsMenuButton||null);
const reportsView=document.createElement('section');reportsView.className='view';reportsView.id='reports';reportsView.innerHTML='<div class="view-head"><div><h2>Laporan bisnis</h2><p>Ringkasan berdasarkan data pesanan di D1.</p></div><button class="secondary" id="exportReport">Unduh CSV</button></div><div class="tools"><label class="report-date">Dari <input class="filter" id="reportFrom" type="date"></label><label class="report-date">Sampai <input class="filter" id="reportTo" type="date"></label><button class="primary" id="applyReport">Terapkan</button></div><div class="stats report-stats"><article class="card"><small>Omzet berhasil</small><strong id="reportRevenue">—</strong></article><article class="card"><small>Midtrans Sandbox</small><strong id="reportMidtrans">—</strong></article><article class="card"><small>Simulasi manual</small><strong id="reportSimulation">—</strong></article><article class="card"><small>Total pesanan</small><strong id="reportOrders">—</strong></article></div><div class="grid"><section class="panel"><div class="panel-head"><h2>Penjualan harian</h2></div><div class="report-chart" id="reportChart"></div></section><section class="panel"><div class="panel-head"><h2>Produk terlaris</h2></div><div class="rank-list" id="reportTop"></div></section></div><section class="panel" style="margin-top:17px"><div class="panel-head"><h2>Peringatan stok</h2></div><div class="stock-list" id="reportStock"></div></section>';document.querySelector('.main').append(reportsView);
const reportStyle=document.createElement('style');reportStyle.textContent='.customer-addresses{display:grid;grid-template-columns:1fr 1fr;gap:10px}.report-date{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:.82rem}.report-chart{height:230px;display:flex;align-items:end;justify-content:flex-start;gap:12px;padding:12px 4px 0;border-bottom:1px solid var(--line);overflow-x:auto}.report-day{flex:1 0 44px;max-width:72px;height:100%;display:grid;grid-template-rows:1fr auto;align-items:end;gap:7px;text-align:center;color:var(--muted);font-size:.68rem}.report-bar-wrap{height:100%;display:flex;align-items:end;justify-content:center;position:relative}.report-bar{display:block;width:min(38px,80%);min-height:6px;border-radius:7px 7px 2px 2px;background:var(--forest);transition:filter .2s,transform .2s}.report-bar-value{position:absolute;left:50%;bottom:calc(var(--bar-height) + 7px);transform:translateX(-50%);white-space:nowrap;color:var(--ink);font-size:.66rem;font-weight:700}.report-day:hover .report-bar{filter:brightness(1.16);transform:translateY(-2px)}.stock-row>span:first-child{min-width:0}.stock-row b,.stock-row small{display:block}.stock-row small{margin-top:2px}.report-stock-meter{display:block;width:min(260px,100%);height:5px;margin-top:7px;background:#ece7de;border-radius:99px;overflow:hidden}.report-stock-meter i{display:block;height:100%;border-radius:inherit;background:var(--green)}.report-stock-meter i.low{background:var(--rust)}@media(max-width:590px){.customer-addresses{grid-template-columns:1fr}.report-chart{overflow:auto}.report-day{flex-basis:42px}.report-bar-value{display:none}}';document.head.append(reportStyle);
const today=new Date().toISOString().slice(0,10),monthAgo=new Date(Date.now()-29*86400000).toISOString().slice(0,10);document.querySelector('#reportFrom').value=monthAgo;document.querySelector('#reportTo').value=today;
async function loadReport(){const from=document.querySelector('#reportFrom').value,to=document.querySelector('#reportTo').value;try{const data=await api(`/api/reports?from=${from}&to=${to}`),summary=data.summary||{};document.querySelector('#reportRevenue').textContent=rupiah(summary.revenue||0);document.querySelector('#reportMidtrans').textContent=rupiah(summary.midtransRevenue||0);document.querySelector('#reportSimulation').textContent=rupiah(summary.simulatedRevenue||0);document.querySelector('#reportOrders').textContent=summary.orderCount||0;const max=Math.max(...data.daily.map(item=>Number(item.revenue)),1);document.querySelector('#reportChart').innerHTML=data.daily.length?data.daily.map(item=>{const height=Math.max(6,Number(item.revenue)/max*160);return `<div class="report-day" title="${rupiah(item.revenue)}"><div class="report-bar-wrap" style="--bar-height:${height}px"><small class="report-bar-value">${rupiah(item.revenue)}</small><span class="report-bar" style="height:${height}px"></span></div><time>${new Date(`${item.date}T00:00:00`).toLocaleDateString('id-ID',{day:'2-digit',month:'short'})}</time></div>`}).join(''):'<div class="empty" style="width:100%">Belum ada penjualan pada periode ini.</div>';document.querySelector('#reportTop').innerHTML=data.topProducts.length?data.topProducts.map((item,index)=>`<div class="rank-item"><span class="rank">${index+1}</span><span><b>${escapeHtml(item.name)}</b><small>${item.quantity} unit</small></span><span class="mini-total">${rupiah(item.total)}</span></div>`).join(''):'<div class="empty">Belum ada produk terjual.</div>';document.querySelector('#reportStock').innerHTML=data.lowStock.length?data.lowStock.map(item=>`<div class="stock-row"><span><b>${escapeHtml(item.name)}</b><small>Tersisa ${item.stock} unit</small><span class="report-stock-meter"><i class="${item.stock<=2?'low':''}" style="width:${Math.min(100,Math.max(8,item.stock*10))}%"></i></span></span><span class="status ${item.stock<=2?'low':''}">${item.stock<=2?'Rendah':'Cukup'}</span></div>`).join(''):'<div class="empty">Stok seluruh produk masih aman.</div>'}catch(error){toast(error.message)}}
reportsMenu.addEventListener('click',()=>{document.querySelectorAll('.menu button,.view').forEach(item=>item.classList.remove('active'));reportsMenu.classList.add('active');reportsView.classList.add('active');document.querySelector('#pageTitle').textContent='Laporan';document.querySelector('#pageSubtitle').textContent='Pantau penjualan, pelanggan, dan stok.';loadReport()});document.querySelector('#applyReport').addEventListener('click',loadReport);document.querySelector('#exportReport').addEventListener('click',()=>{const from=document.querySelector('#reportFrom').value,to=document.querySelector('#reportTo').value;location.href=`/api/reports/export.csv?from=${from}&to=${to}`});
